import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:go_router/go_router.dart';
import 'package:url_launcher/url_launcher.dart';
import '../../../core/theme/app_theme.dart';
import '../../../core/widgets/groopx_ui.dart';
import '../data/chat_api.dart';
import '../domain/chat_models.dart';

class SharedMediaScreen extends StatefulWidget{const SharedMediaScreen({super.key,required this.conversationId});final String conversationId;@override State<SharedMediaScreen> createState()=>_SharedMediaScreenState();}
class _SharedMediaScreenState extends State<SharedMediaScreen>{List<SharedMediaItem> items=const[];bool loading=true;String? error;String filter='all';
  @override void initState(){super.initState();_load();}
  Future<void> _load()async{setState((){loading=true;error=null;});try{final value=await ChatApi.instance.sharedMedia(widget.conversationId);if(mounted)setState(()=>items=value);}catch(_){if(mounted)setState(()=>error='Shared files load nahi hui.');}finally{if(mounted)setState(()=>loading=false);}}
  List<SharedMediaItem> get visible=>switch(filter){'media'=>items.where((item)=>item.kind=='image'||item.kind=='video').toList(),'links'=>items.where((item)=>item.kind=='link').toList(),'documents'=>items.where((item)=>item.kind=='file').toList(),'audio'=>items.where((item)=>item.kind=='audio').toList(),'locations'=>items.where((item)=>item.kind=='location').toList(),_=>items};
  bool get _usesList=>filter=='links'||filter=='documents'||filter=='audio'||filter=='locations';
  @override Widget build(BuildContext context)=>Scaffold(backgroundColor:AppColors.background,appBar:AppBar(title:const Text('Media, links & docs')),body:GroopXBackground(child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(16,14,16,8),child:SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:['all','media','links','documents','audio','locations'].map((value)=>Padding(padding:const EdgeInsets.only(right:8),child:ChoiceChip(label:Text(value[0].toUpperCase()+value.substring(1)),selected:filter==value,onSelected:(_)=>setState(()=>filter=value)))).toList()))),Expanded(child:loading?const Center(child:CircularProgressIndicator()):error!=null?GroopXEmptyState(icon:Icons.cloud_off_outlined,title:'Unable to load',message:error!,actionLabel:'Retry',actionIcon:Icons.refresh,onAction:_load):visible.isEmpty?_empty():RefreshIndicator(onRefresh:_load,child:_usesList?ListView.separated(physics:const AlwaysScrollableScrollPhysics(),padding:const EdgeInsets.all(16),itemCount:visible.length,separatedBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(_,index)=>_listTile(visible[index])):GridView.builder(physics:const AlwaysScrollableScrollPhysics(),padding:const EdgeInsets.all(16),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,crossAxisSpacing:10,mainAxisSpacing:10,childAspectRatio:1.05),itemCount:visible.length,itemBuilder:(_,index)=>_tile(visible[index]))))])));
  Widget _empty(){final label=switch(filter){'media'=>'photos ya videos','links'=>'links','documents'=>'documents','audio'=>'audio files','locations'=>'locations',_=>'photos, videos, links, audio, documents ya locations'};return GroopXEmptyState(icon:filter=='links'?Icons.link_off:filter=='locations'?Icons.location_off_outlined:Icons.perm_media_outlined,title:'Nothing shared yet',message:'Chat mein share kiye hue $label yahan dikhenge.');}
  Future<void> _open(SharedMediaItem item)async{if(item.url.isEmpty)return;if(item.kind=='link'||item.kind=='location'){var opened=false;try{final uri=Uri.tryParse(item.url);opened=uri!=null&&await launchUrl(uri,mode:LaunchMode.externalApplication);}catch(_){}if(!opened&&mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(item.kind=='location'?'Map open nahi hua.':'Link open nahi hua.')));return;}if(mounted)context.push('/attachment',extra:<String,String>{'kind':item.kind,'name':item.name,'url':item.url});}
  Future<void> _copyLink(SharedMediaItem item)async{await Clipboard.setData(ClipboardData(text:item.url));if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Link copied.')));}
  Widget _tile(SharedMediaItem item){final media=item.kind=='image'&&item.url.isNotEmpty;return Card(clipBehavior:Clip.antiAlias,child:InkWell(onTap:item.url.isEmpty?null:()=>_open(item),onLongPress:item.kind=='link'?()=>_copyLink(item):null,child:media?Image.network(item.url,fit:BoxFit.cover,errorBuilder:(_,__,___)=>_file(item)):_file(item)));}
  Widget _listTile(SharedMediaItem item)=>Card(child:ListTile(onTap:item.url.isEmpty?null:()=>_open(item),onLongPress:item.kind=='link'?()=>_copyLink(item):null,leading:CircleAvatar(backgroundColor:AppColors.purple.withValues(alpha:.1),child:Icon(_icon(item.kind),color:AppColors.purple)),title:Text(item.kind=='link'?_host(item.url):item.name,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(item.kind=='link'?item.url:_date(item),maxLines:2,overflow:TextOverflow.ellipsis),trailing:item.kind=='link'?IconButton(tooltip:'Copy link',onPressed:()=>_copyLink(item),icon:const Icon(Icons.copy_outlined)):const Icon(Icons.chevron_right)));
  Widget _file(SharedMediaItem item)=>Padding(padding:const EdgeInsets.all(14),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(_icon(item.kind),size:38,color:AppColors.purple),const SizedBox(height:10),Text(item.kind=='link'?_host(item.url):item.name,maxLines:2,overflow:TextOverflow.ellipsis,textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.w600)),const SizedBox(height:5),Text(_date(item),style:const TextStyle(fontSize:11,color:AppColors.muted))]));
  String _date(SharedMediaItem item)=>'${item.createdAt.day}/${item.createdAt.month}/${item.createdAt.year}';
  String _host(String value){final host=Uri.tryParse(value)?.host;return host==null||host.isEmpty?value:host.replaceFirst(RegExp(r'^www\.'),'');}
  IconData _icon(String kind)=>switch(kind){'video'=>Icons.play_circle_outline,'audio'=>Icons.audio_file_outlined,'image'=>Icons.image_outlined,'link'=>Icons.link,'location'=>Icons.location_on_outlined,_=>Icons.insert_drive_file_outlined};
}
